import { queueReveal } from './components/reveal-queue.js';
import './components/reveal-overlay.js';
import { dgnScore } from './app/dgn-reels.js';
import { ETH_DIVISOR } from './app/chain-config.js';
import { readLightweightModePreference, writeLightweightModePreference } from './app/ui-preferences.js';
import { isMuted, setMuted, warmup } from './app/jackpot-sfx.js';
import { initButtonFeedback } from './app/button-feedback.js';
import { readDegeneretteSpeed, writeDegeneretteSpeed } from './app/degenerette-preferences.js';

// Exercise the same delegated pointer/keyboard feedback as the live app.
initButtonFeedback();

// Degenerette lanes: [symbol, color, wild]; a wild lane is 0x40 | symbol.
const pack = traits => traits.reduce((word, [sym, col, wild], q) => word | ((wild ? 0x40 | sym : col * 8 + sym) << (q * 8)), 0) >>> 0;
const player = pack([[6, 0, true], [2, 4], [5, 2], [3, 1]]);
const houses = [
  pack([[6, 7], [1, 4], [5, 2], [4, 3]]),
  pack([[5, 3], [1, 2], [4, 5], [2, 4]]),
  pack([[6, 0, true], [2, 7], [4, 5], [2, 4]]),
  player,
];
export function previewSequence(kind = '1') {
  if (kind === 'eth-box' || kind === 'wwxrp-box') {
    const spinType = kind === 'eth-box' ? 'eth' : 'wwxrp';
    return { kind: 'lootbox', legs: [{
      legType: 'spin', spinType,
      payout: spinType === 'eth' ? 2n * 10n ** 16n / ETH_DIVISOR : 11n * 10n ** 18n,
      reels: [{ spinIndex: 0, playerTicket: player, resultTicket: houses[0], score: dgnScore(player, houses[0]) }],
    }] };
  }
  if (kind === 'box-bust') return {
    kind: 'lootbox', legs: [{ ...makeBox('flip'), survived: false, payout: 0n }],
  };
  if (kind === 'degenesis') return {
    kind, degenesisDay: 3,
    result: { flip: 1500n * 10n ** 18n, dgnrs: 2n * 10n ** 18n,
      wwxrp: 30n * 10n ** 18n, normalPasses: 2, highPasses: 0 },
  };
  if (kind === 'eth') {
    const payouts = [2n, 0n, 1n, 3n].map(value => value * 10n ** 16n / ETH_DIVISOR);
    return {
      kind: 'degenerette', currency: 0, heroIdx: 0,
      amountPerSpin: 10n ** 16n / ETH_DIVISOR,
      totalPayout: payouts.reduce((sum, value) => sum + value, 0n),
      lootboxAwarded: true, lootboxEth: 3n * 10n ** 16n / ETH_DIVISOR,
      spins: payouts.map((payout, i) => ({
        spinIndex: i, playerTraits: player, houseTraits: houses[i],
        score: dgnScore(player, houses[i]), payout,
      })),
    };
  }
  if (kind === 'box' || kind === 'record') return {
    kind: kind === 'record' ? 'record-bounty' : 'lootbox',
    ...(kind === 'record' ? { spin: makeBox('record') } : { legs: [makeBox('flip')] }),
  };
  const count = Math.max(1, Math.min(25, Number(kind) || 1));
  const spins = Array.from({ length: count }, (_, i) => ({
    spinIndex: i, playerTraits: player, houseTraits: houses[i % houses.length],
    score: dgnScore(player, houses[i % houses.length]),
    payout: i % houses.length === 1 ? 0n : 1500n * 10n ** 18n,
  }));
  return {
    kind: 'degenerette', headline: 'DEGENERETTE', currency: 1, heroIdx: 0,
    amountPerSpin: 100n * 10n ** 18n,
    totalPayout: 2n * spins.reduce((sum, row) => sum + row.payout, 0n), spins,
  };
}
function makeBox(spinType) {
  return {
    legType: 'spin', spinType, survived: true, payout: 3000n * 10n ** 18n,
    preSurvivalPayout: 1500n * 10n ** 18n, heroQuadrant: 0,
    reels: [0, 1, 2].map(i => ({
      spinIndex: i, heroQuadrant: 0, playerTicket: player,
      resultTicket: houses[i], score: dgnScore(player, houses[i]),
    })),
  };
}
const lightweight = document.getElementById('pop-demo-lightweight');
lightweight.checked = readLightweightModePreference();
lightweight.addEventListener('change', () => writeLightweightModePreference(lightweight.checked));
const mute = document.getElementById('pop-demo-mute');
mute.checked = isMuted();
mute.addEventListener('change', () => setMuted(mute.checked));
const speed = document.getElementById('pop-demo-speed');
speed.value = String(readDegeneretteSpeed());
speed.addEventListener('change', () => writeDegeneretteSpeed(Number(speed.value)));
const requestedPreview = new URLSearchParams(location.search).get('preview');
const preview = document.getElementById('pop-demo-kind');
if ([...preview.options].some(option => option.value === requestedPreview)) preview.value = requestedPreview;
document.getElementById('pop-demo-open').addEventListener('click', () => {
  warmup();
  const kind = document.getElementById('pop-demo-kind').value;
  const sequence = previewSequence(kind);
  if (kind === 'eth') sequence.lootboxPresentationId = `demo-eth-luckbox:${++ethPreviewCount}`;
  queueReveal(sequence);
  if (kind === 'eth') queueReveal({
    kind: 'lootbox', title: 'DEGENERETTE LUCKBOX',
    presentationId: sequence.lootboxPresentationId,
    amountWei: sequence.lootboxEth,
    legs: [{ legType: 'dgnrs', amount: 7n * 10n ** 18n }],
  });
});
let ethPreviewCount = 0;
